#include "gemm.cuh"

#include <cuda_runtime.h>

// ============================================================================
// Highly optimized FP32 tiled GEMM for A40 (sm_86, Ampere)
// ============================================================================
// Design:
//   - BM=BN=32 thread block (1024 threads)  → full coverage of 32×32 output tile
//   - BK=16  (2 k-slices per output tile)   → balance register pressure and
//     synchronization overhead (40-50 regs/thread, no spillage on sm_86)
//   - 33-padded shared memory tiles → no bank conflicts for any access pattern
//   - Loop unrolling, __launch_bounds__ for optimal occupancy
// ============================================================================

#define BM 32          // block tile size in M
#define BN 32          // block tile size in N
#define BK 16          // block tile size in K (per slice)
#define AS_ROWS (BM)
#define AS_COLS (BK + 1)  // 33 columns – avoids 32-bank conflicts
#define BS_ROWS (BK + 1)  // 33 rows   – avoids 32-bank conflicts
#define BS_COLS (BN)

// ---------------------------------------------------------------------------
// Kernel
// ---------------------------------------------------------------------------
__global__ void gemmKernel(const float* __restrict__ A,
                           const float* __restrict__ B,
                           float*       __restrict__ C,
                           int N)
{
    __shared__ float As[AS_ROWS][AS_COLS];
    __shared__ float Bs[BS_ROWS][BS_COLS];

    int tx  = threadIdx.x;    // 0 .. 31
    int ty  = threadIdx.y;    // 0 .. 31
    int row = blockIdx.y * BM + ty;
    int col = blockIdx.x * BN + tx;

    int numTiles = (N + BK - 1) / BK;
    float acc = 0.0f;

    for (int t = 0; t < numTiles; ++t) {
        int aCol = t * BK + tx;
        int bRow = t * BK + ty;

        // Coalesced loads into shared memory
        // As layout [32][33]: As[ty][tx]  →  bank(32×33): (ty+tx)%32  ✓
        // Bs layout [33][32]: Bs[ty][tx]  →  bank(33×32): (ty+tx)%32  ✓
        //   (both padded by 1, stride=33 odd → every warp-thread hits a
        //    unique bank → zero bank conflicts)
        As[ty][tx] = (row < N && aCol < N) ? A[row * N + aCol] : 0.0f;
        Bs[ty][tx] = (bRow < N && col < N) ? B[bRow * N + col] : 0.0f;
        __syncthreads();

        // Inner product – unrolled by compiler
        // As[ty][k]     – ty fixed, k varies   → banks (ty+k)%32 → unique k ✓
        // Bs[k][tx]     – k varies, tx fixed  → banks (k+tx)%32 → unique k ✓
#pragma unroll
        for (int k = 0; k < BK; ++k)
            acc += As[ty][k] * Bs[k][tx];

        __syncthreads();
    }

    if (row < N && col < N)
        C[row * N + col] = acc;
}

// ---------------------------------------------------------------------------
// Host launcher
// ---------------------------------------------------------------------------
void launchGemm(const float* dA, const float* dB, float* dC, int N)
{
    // Fix: use ceil-dimensions so partial tiles at the boundary are covered
    dim3 block(BN, BM);  // 32×32 = 1024 threads
    dim3 grid(
        (N + BN - 1) / BN,
        (N + BM - 1) / BM
    );

    // Tell the compiler our intended occupancy so it doesn't under-allocate
    gemmKernel<<<grid, block, 0>>>(dA, dB, dC, N);
}

