#include "gemm.cuh"

#include <cuda_runtime.h>

// ============================================================================
// Highly optimized FP32 tiled GEMM for A40 (sm_86, Ampere)
// ============================================================================
// Block: 32x32 = 1024 threads covering a 32x32 output tile
// Tile-K: 16 (2 k-slices per output tile) – keeps register usage low enough
// Shared memory: 33-padded tiles for zero bank conflicts
// Each thread handles one element of the output tile.
// ============================================================================

#define BM 32          // block tile size in M
#define BN 32          // block tile size in N
#define BK 16          // block tile size in K (per slice)
#define PAD (BK > BN ? BK + 1 : BN + 1)

// ---------------------------------------------------------------------------
// Kernel
// ---------------------------------------------------------------------------
__global__ void gemmKernel(const float* __restrict__ A,
                           const float* __restrict__ B,
                           float*       __restrict__ C,
                           int N)
{
    // 33-padded shared memory tiles – avoids 32-bank conflicts
    __shared__ float As[BM][BK + 1];
    __shared__ float Bs[BK + 1][BN + 1];

    const int tx = threadIdx.x;    // 0 .. 31
    const int ty = threadIdx.y;    // 0 .. 31
    const int row = blockIdx.y * BM + ty;
    const int col = blockIdx.x * BN + tx;

    const int numTiles = (N + BK - 1) / BK;
    float acc = 0.0f;

    for (int t = 0; t < numTiles; ++t) {
        const int aCol = t * BK + tx;
        const int bRow = t * BK + ty;

        // Guarded loads – use explicit ifs so the compiler does NOT evaluate
        // the out-of-bounds branch.
        if (row < N && aCol < N)
            As[ty][tx] = A[row * N + aCol];
        else
