    // Layout:
    //   As[BM][BN + SM_PAD]  – row-tiling from A
    //   Bs[BM][BN + SM_PAD]  – row-tiling from B (Bs[row_in_tile][col_offset])
    __shared__ float As[BM][BN + SM_PAD];
    __shared__ float Bs[BM][BN + SM_PAD];

    const int tx  = threadIdx.x;      // 0 .. 31
    const int ty  = threadIdx.y;      // 0 .. 31
    const int row = blockIdx.y * BM + ty;
    const int col = blockIdx.x * BN + tx;

    const int numTiles = (N + BK - 1) / BK;
