#include "gemm.cuh"

#include <cuda_runtime.h>

// ============================================================================
// Optimized tiled GEMM for A40 (sm_86, Ampere)
//
// Strategy:
//   BM=16, BN=16, BK=32
//   16×16 block (256 threads), each computes one output element.
//   BK=32 → one shared-mem tile per K-slice, giving 32 MACs per thread per
//           load → good compute/memory ratio.
//   Registers per thread ≈ 20 → 6 blocks/SM → 100 % occupancy.
//
//   33-padded shared memory (33 = 32+1, odd stride → no 32-bank conflicts).
// ============================================================================

#define BM 16
#define BN 16
#define BK 32
#define SPM (BK + 1)   // 33 columns for As
#define SPC (BN + 1)   // 17 columns for Bs

// ---------------------------------------------------------------------------
// Kernel
// ---------------------------------------------------------------------------
__global__ void __launch_bounds__(256, 6)
gemmKernel(const float* __restrict__ A,
           const float* __restrict__ B,
           float*       __restrict__ C,
           int N)
{
    // Shared-memory tiles, 33-padded to avoid bank conflicts.
    // As[16][33] – 528 floats = 2112 bytes  (A tile, row-major)
    // Bs[17][17] – 289 floats = 1156 bytes  (B tile, transposed via col index)
    __shared__ float As[BM][SPM];
    __shared__ float Bs[BK][SPC];

    const int tx = threadIdx.x;    // 0 .. 15
    const int ty = threadIdx.y;    // 0 .. 15
    const int row = blockIdx.y * BM + ty;
    const int col = blockIdx.x * BN + tx;

    const int numTiles = (N + BK - 1) / BK;
    float acc = 0.0f;

    for (int t = 0; t < numTiles; ++t) {
        // ---- Load A tile  (row-major, 33-padded) ----
        // Thread (tx,ty) contributes column tx of the A tile.
        // The 16 threads in a row cooperatively load 16 consecutive floats
        // which coalesce into one 64-byte transaction.
        {
            const int aCol = t * BK + tx;
            if (row < N && aCol < N)
                As[ty][tx] = A[row * N + aCol];
            else
                As[ty][tx] = 0.0f;
        }

        // ---- Load B tile  (transposed: Bs[col_offset][row_in_tile]) ----
        // We want Bs[k][tx] in the inner loop where k=0..31, tx=0..15.
        // Load into Bs[tx][ty] so that Bs[k][tx] = Bs[k][tx] directly.
        {
            const int bRow = t * BK + ty;
