#define WMMA_M 16
#define WMMA_N 16
#define WMMA_K 16
#define FRAG_ROWS 16   // number of WMMA_M rows per warp result
#define FRAG_COLS 8    // number of WMMA_N columns per WMMA tile

// Each 16x16 warp tile = two 16x8 WMMA fragments
static constexpr int warp_rows = WMMA_M;        // 16
static constexpr int warp_cols = WMMA_N;         // 16

// Shared memory for tiles (loaded as TF32-compatible float)
#define BM 16
#define BN 16
#define BK 32  // K-tile size for loading (2 k-slices of 16)
#define SM_PAD 1

__shared__ float sA[BM][BK + SM_PAD];   // 16×33
__shared__ float sB[BK + SM_PAD][BN];   // 33×16

