gemmWmmaKernel(const float* __restrict__ A,
               const float* __restrict__ B,
               float*       __restrict__ C,
               int N)
{
    int tx = threadIdx.x;
    int ty = threadIdx.y;

    // Each thread handles one output element
    int row = blockIdx.y * BM + ty;
    int col = blockIdx.x * BN + tx;

    // Use __shared__ wmma fragments
    // We'll accumulate in registers
    float acc = 0.0f;
    int numTiles = (N + BK - 1) / BK;

    for (int t = 0; t < numTiles; ++t) {
        // ---- Load A tile (row-major) ----
        {
            const int aCol = t * BK + tx;
            if (row < N && aCol < N)
                sA[ty][tx] = A[row * N + aCol];
            else
                sA[ty][tx] = 0.0f;
