gemmKernel(const float* __restrict__ A,
           const float* __restrict__ B,
           float*       __restrict__ C,
           int N)
{
    const int tx = threadIdx.x;
    const int ty = threadIdx.y;
    const int row = blockIdx.y * BM + ty;
    const int col = blockIdx.x * BN + tx;

    const int numTiles = (N + BK - 1) / BK;
    float acc = 0.0f;

    if (numTiles == 0) {
        if (row < N && col < N) C[row * N + col] = acc;
        return;
    }

    // ---- Load first tile ----
    {
        const int aCol = tx;
        const int bRow = ty;
        if (row < N && aCol < N) As0[ty][tx] = A[row * N + aCol];
        else As0[ty][tx] = 0.0f;
        if (bRow < N && col < N) Bs0[ty][tx] = B[bRow * N + col];
        else Bs0[ty][tx] = 0.0f;
    }
    __syncthreads();

    int cur = 0;  // 0 or 1 for double buffer selection

    for (int t = 0; t < numTiles; ++t) {
        // ---- Compute with current tile ----
#pragma unroll
