#include "gemm.cuh"

#include <cuda_runtime.h>

// ============================================================================
// Optimized tiled GEMM for A40 (sm_86, Ampere)
//
// BM=BN=BK=16, 16x16 block (256 threads), 6 blocks/SM → 100% occupancy.
// ============================================================================

#define BM 16
#define BN 16
#define BK 16
#define PAD 17

__shared__ float As[BM][PAD];
__shared__ float Bs[BK][PAD];

__global__ void __launch_bounds__(256, 6)
gemmKernel(const float* __restrict__ A,
           const float* __restrict__ B,
           float*       __restrict__ C,
           int N)
{
    const int tx = threadIdx.x;
    const int ty = threadIdx.y;
    const int row = blockIdx.y * BM + ty;
    const int col = blockIdx.x * BN + tx;

    const int numTiles = (N + BK - 1) / BK;
    float acc = 0.0f;

    for (int t = 0; t < numTiles; ++t) {
        // ---- Load A tile ----
        {
            const int aCol = t * BK + tx;
            if (row < N && aCol < N)
                As[ty][tx] = A[row * N + aCol];
            else
                As[ty][tx] = 0.0f;
        }

        // ---- Load B tile ----
        {
            const int bRow = t * BK + ty;
            if (bRow < N && col < N)
                Bs[ty][tx] = B[bRow * N + col];
            else
                Bs[ty][tx] = 0.0f;
        }

        __syncthreads();

        // ---- Inner product ----
#pragma unroll
        for (int k = 0; k < BK; ++k)
            acc += As[ty][k] * Bs[k][tx];

        __syncthreads();
    }

    if (row < N && col < N)
        C[row * N + col] = acc;
}

void launchGemm(const float* dA, const float* dB, float* dC, int N)
{
    dim3 block(BN, BM);
    dim3 grid((N + BN - 1) / BN, (N + BM - 1) / BM);
    gemmKernel<<<grid, block>>>(dA, dB, dC, N);
}

