#define __CUDA_INCLUDE_COMPILER_INTERNAL_HEADERS__
#include <cuda_runtime.h>
#include <crt/mma.h>

__global__ void testKernel(int N) {
    int warpIdx = threadIdx.x / 32;
    int laneIdx = threadIdx.x % 32;

    // Simple TF32 WMMA: each warp loads 16x16 A and 16x8 B from global memory
    // and computes mma_sync.
    if (warpIdx == 0) {
        nvcuda::wmma::fragment<nvcuda::wmma::matrix_a, 16, 16, 8, nvcuda::wmma::precision::tf32, nvcuda::wmma::row_major> a;
        nvcuda::wmma::fragment<nvcuda::wmma::matrix_b, 16, 16, 8, nvcuda::wmma::precision::tf32, nvcuda::wmma::col_major> b;
        nvcuda::wmma::fragment<nvcuda::wmma::accumulator, 16, 16, 8, float> c;

        nvcuda::wmma::fill_fragment(c, 0.0f);
        nvcuda::wmma::fill_fragment(a, 0.0f);
        nvcuda::wmma::fill_fragment(b, 0.0f);

        float testA[16][16];
        float testB[16][16];
        for (int i = 0; i < 16; i++)
            for (int j = 0; j < 16; j++) {
                testA[i][j] = 1.0f;
                testB[i][j] = 1.0f;
            }

        nvcuda::wmma::load_matrix_sync(a, &testA[0][0], 16);
        nvcuda::wmma::load_matrix_sync(b, &testB[0][0], 16);
        nvcuda::wmma::mma_sync(c, a, b, c);

        float result[16][16];
        nvcuda::wmma::store_matrix_sync(&result[0][0], c, 16, nvcuda::wmma::mem_row_major);
    }
}

int main() {
    testKernel<<<1, 128>>>(16);
    cudaDeviceSynchronize();
    printf("OK\n");
    return 0;
}
