#define __CUDA_INCLUDE_COMPILER_INTERNAL_HEADERS__
#include <cuda_runtime.h>
#include <crt/mma.h>
#include <cmath>
#include <cstdio>

using namespace nvcuda::wmma;

#define TILE 256  // tile size for output

__global__ void tf32GemmKernel(const float* A, const float* B, float* C, int N) {
    int warpIdx = threadIdx.x / 32;
    int laneIdx = threadIdx.x % 32;
    int blockWarp = blockIdx.y * gridDim.x + blockIdx.x;
    int totalWarpsPerDim = (N + 15) / 16;

    int blockCol = blockWarp % totalWarpsPerDim;
    int blockRow = blockWarp / totalWarpsPerDim;

    int gRow = blockRow * 16;
    int gCol = blockCol * 16;

    if (gRow + 16 > N || gCol + 16 > N) return;

    int numK = (N + 7) / 8;

    fragment<matrix_a, 16, 16, 8, precision::tf32, row_major> fa;
    fragment<matrix_b, 16, 16, 8, precision::tf32, col_major> fb;
    fragment<accumulator, 16, 16, 8, float> fc;
    fill_fragment(fc, 0.0f);

    for (int t = 0; t < numK; ++t) {
        load_matrix_sync(fa, &A[(gRow)*N + t*8], N);
        load_matrix_sync(fb, &B[(t*8)*N + gCol], N);
        mma_sync(fc, fa, fb, fc);
    }

    store_matrix_sync(&C[gRow * N + gCol], fc, N, mem_row_major);
}

int main() {
    int N = 256;
    size_t bytes = N * N * sizeof(float);
    float *hA = (float*)malloc(bytes), *hB = (float*)malloc(bytes), *hC = (float*)malloc(bytes);

    for (int i = 0; i < N; i++)
        for (int j = 0; j < N; j++) {
            hA[i*N+j] = (rand()%1000)/1000.0 - 0.5;
            hB[i*N+j] = (rand()%1000)/1000.0 - 0.5;
            hC[i*N+j] = 0.0f;
        }

    float *dA, *dB, *dC;
    cudaMalloc(&dA, bytes); cudaMalloc(&dB, bytes); cudaMalloc(&dC, bytes);
    cudaMemcpy(dA, hA, bytes, cudaMemcpyHostToDevice);
    cudaMemcpy(dB, hB, bytes, cudaMemcpyHostToDevice);

    int totalWarps = ((N+15)/16) * ((N+15)/16);
    int blocks = (totalWarps + 127) / 128;

    tf32GemmKernel<<<blocks, 128>>>(dA, dB, dC, N);
    cudaDeviceSynchronize();

    cudaMemcpy(hC, dC, bytes, cudaMemcpyDeviceToHost);

    // CPU reference (simple)
    float *hR = (float*)malloc(bytes);
    for (int i = 0; i < N; i++)
        for (int j = 0; j < N; j++) {
            double acc = 0;
            for (int k = 0; k < N; k++)
                acc += (double)hA[i*N+k] * (double)hB[k*N+j];
            hR[i*N+j] = (float)acc;
        }

    double mse = 0;
    for (int i = 0; i < N*N; i++) {
        double d = (double)hC[i] - (double)hR[i];
        mse += d * d;
    }
    mse /= N*N;
    printf("N=%d MSE=%.6e\n", N, mse);

    free(hA); free(hB); free(hC); free(hR);
    cudaFree(dA); cudaFree(dB); cudaFree(dC);
    return 0;
}
