// ============================================================================
// Optimized tiled GEMM for A40 (sm_86, Ampere)
//
// BM=BN=64, BK=16, 16x16 block = 256 threads, 4x4 register blocking.
// Each thread handles 4x4 output elements = 64 MACs per k-slice.
// Shared memory: As[64][17], Bs[17][64] with padding.
// 2 blocks per SM (65536/124/256 ≈ 2).
// ============================================================================

#define BM 64
#define BN 64
#define BK 16
#define PAD_A (BN + 1)  // 65 cols for As
#define PAD_B (BK + 1)  // 17 rows for Bs

__shared__ float As[BM][PAD_A];
__shared__ float Bs[BK][PAD_B];

__global__ void __launch_bounds__(256, 2)
gemmKernel(const float* __restrict__ A,
           const float* __restrict__ B,
           float*       __restrict__ C,
           int N)
{
    const int tx = threadIdx.x;  // 0..15
    const int ty = threadIdx.y;  // 0..15

    // Each thread handles 4 rows x 4 cols of the 64x64 output tile
    const int row0 = blockIdx.y * BM + ty * 4;
    const int row1 = row0 + 1;
    const int row2 = row0 + 2;
    const int row3 = row0 + 3;
    const int col0 = blockIdx.x * BN + tx * 4;
    const int col1 = col0 + 1;
    const int col2 = col0 + 2;
    const int col3 = col0 + 3;

    const int numTiles = (N + BK - 1) / BK;
