        __syncthreads();

        // Inner product – unrolled by compiler
        // As[ty][k]     – ty fixed, k varies   → banks (ty+k)%32 → unique k ✓
        // Bs[k][tx]     – k varies, tx fixed  → banks (k+tx)%32 → unique k ✓
#pragma unroll
        for (int k = 0; k < BK; ++k)
            acc += As[ty][k] * Bs[k][tx];

        __syncthreads();
    }

    if (row < N && col < N)
        C[row * N + col] = acc;
}

