#include "gemm.cuh"

#include <cuda_runtime.h>

// ============================================================================
// Highly optimized FP32 tiled GEMM for A40 (sm_86, Ampere)
// ============================================================================
// Block: 32x32 = 1024 threads covering a 32x32 output tile
// Tile-K: 16 (2 k-slices per output tile) – keeps register usage low
// Shared memory: 33-padded tiles for zero bank conflicts
// ============================================================================

#define BM 32          // block tile size in M
#define BN 32          // block tile size in N
#define BK 16          // block tile size in K (per slice)
#define SM_PAD 1       // 1 extra column/row for bank-conflict avoidance
// Each shared-mem tile is 33 wide so stride is odd → no bank conflicts

// ---------------------------------------------------------------------------
// Kernel
// ---------------------------------------------------------------------------
__global__ void gemmKernel(const float* __restrict__ A,
                           const float* __restrict__ B,
                           float*       __restrict__ C,
                           int N)
{
    // Shared memory tiles – 33-padded to avoid 32-bank conflicts.
    // Layout:
    //   As[BM][BN + SM_PAD]  – row-tiling from A
    //   Bs[BM][BN + SM_PAD]  – row-tiling from B (Bs[row_in_tile][col_offset])
    __shared__ float As[BM][BN + SM_PAD];
    __shared__ float Bs[BM][BN + SM_PAD];

    const int tx  = threadIdx.x;      // 0 .. 31
    const int ty  = threadIdx.y;      // 0 .. 31
    const int row = blockIdx.y * BM + ty;
    const int col = blockIdx.x * BN + tx;

    const int numTiles = (N + BK - 1) / BK;
    float acc = 0.0f;

    for (int t = 0; t < numTiles; ++t) {
        const int aCol = t * BK + tx;
        const int bRow = t * BK + ty;

        if (row < N && aCol < N)
            As[ty][tx] = A[row * N + aCol];
        else
            As[ty][tx] = 0.0f;

        if (bRow < N && col < N)
            Bs[ty][tx] = B[bRow * N + col];
        else
            Bs[ty][tx] = 0.0f;

        __syncthreads();

        // Each thread accumulates the inner product of its row of A
        // (from shared memory) with its column of B.
        // As[ty][k]  →  k = 0 .. BK-1  (valid: As has BN+1 cols ≥ BK)
        // Bs[k][tx]  →  k = 0 .. BK-1, tx = 0 .. 31  (valid: Bs has BN+1 cols)
#pragma unroll
        for (int k = 0; k < BK; ++k)
            acc += As[ty][k] * Bs[k][tx];

        __syncthreads();
    }

    if (row < N && col < N)
        C[row * N + col] = acc;
}

// ---------------------------------------------------------------------------
// Host launcher
// ---------------------------------------------------------------------------
void launchGemm(const float* dA, const float* dB, float* dC, int N)
{
    dim3 block(BN, BM);                     // 32 x 32 = 1024 threads
    dim3 grid((N + BN - 1) / BN,
              (N + BM - 1) / BM);            // ceil-dimension grid

    gemmKernel<<<grid, block>>>(dA, dB, dC, N);
}

