            const int bRow = t * BK + ty;
            if (bRow < N && col < N)
                sB[ty][tx] = B[bRow * N + col];
            else
                sB[ty][tx] = 0.0f;
        }

        __syncthreads();

        // ---- Inner product (FP32, non-tensor) ----
#pragma unroll
        for (int k = 0; k < BK; ++k)
            acc += sA[ty][k] * sB[k][tx];

        __syncthreads();
    }

    if (row < N && col < N)
        C[row * N + col] = acc;
}

