// ============================================================================
// Optimized tiled GEMM for A40 (sm_86, Ampere)
//
// Strategy: BM=BN=BK=16, 16x16 block (256 threads), 100% occupancy.
// Each thread computes one output element.
// BK=32 with 2-element loads per thread to reduce sync overhead.
// 33-padded shared memory for zero bank conflicts.
// ============================================================================

// BM=16, BN=16 output tile per block
// BK=32 K-dimension per k-slice (each thread loads 2 A elements, 2 B elements)
#define BM 16
#define BN 16
#define BK 32

// As: 16 rows x 33 cols (32 data + 1 padding)
// Bs: 33 rows x 17 cols (32 data + 1 padding)
// Each thread (tx,ty) loads 2 A elements (columns tx, tx+16) and 2 B elements (rows ty, ty+16)
#define AS_COLS (BK + 1)   // 33
#define BS_ROWS (BK + 1)   // 33

// ---------------------------------------------------------------------------
// Kernel
// ---------------------------------------------------------------------------
__global__ void __launch_bounds__(256, 1)
gemmKernel(const float* __restrict__ A,
           const float* __restrict__ B,
           float*       __restrict__ C,
           int N)
{
    __shared__ float As[BM][AS_COLS];  // 16x33
    __shared__ float Bs[BS_ROWS][BN];  // 33x16

    const int tx = threadIdx.x;  // 0..15
    const int ty = threadIdx.y;  // 0..15
    const int row = blockIdx.y * BM + ty;
    const int col = blockIdx.x * BN + tx;

    const int numTiles = (N + BK - 1) / BK;
    float acc = 0.0f;

    for (int t = 0; t < numTiles; ++t) {
        // ---- Load A tile (16×32) ----
        // Thread (tx,ty) contributes 2 elements per row: columns tx and tx+16
        {
            const int aCol0 = t * BK + tx;
            const int aCol1 = t * BK + tx + 16;
            if (row < N && aCol0 < N)
                As[ty][tx] = A[row * N + aCol0];
            else
                As[ty][tx] = 0.0f;
            if (row < N && aCol1 < N)
                As[ty][tx + 16] = A[row * N + aCol1];
            else
                As[ty][tx + 16] = 0.0f;
        }

        // ---- Load B tile (32×16) ----
        // Thread (tx,ty) contributes 2 elements per column: rows ty and ty+16
        {
            const int bRow0 = t * BK + ty;
            const int bRow1 = t * BK + ty + 16;
            if (bRow0 < N && col < N)
                Bs[ty][tx] = B[bRow0 * N + col];
            else
                Bs[ty][tx] = 0.0f;
            if (bRow1 < N && col < N)
                Bs[ty + 16][tx] = B[bRow1 * N + col];
            else
                Bs[ty + 16][tx] = 0.0f;
        }

        __syncthreads();

        // ---- Inner product (32 MACs) ----
#pragma unroll
        for (int k = 0; k < BK; ++k)
            acc += As[ty][k] * Bs[k][tx];

        __syncthreads();
    }

    if (row < N && col < N)
        C[row * N + col] = acc;
}

void launchGemm(const float* dA, const float* dB, float* dC, int N)
{
    dim3 block(BN, BM);  // 16x16 = 256 threads
    dim3 grid((N + BN - 1) / BN, (N + BM - 1) / BM);
    gemmKernel<<<grid, block>>>(dA, dB, dC, N);
}

