// ============================================================================
// Optimized tiled GEMM for A40 (sm_86, Ampere)
// Uses register tiling with 32×16 blocks, 512 threads.
// Each thread handles 2×1 output elements (64 MACs per k-slice).
// 3 blocks/SM → 100% occupancy.
// BM=32, BN=16, BK=16, TM=2, TN=1
//
// Shared memory: As[32][17] (A tile), Bs[17][17] (B tile)
// Thread (tx,ty): tx=0..15, ty=0..31
// Handles rows: blockIdx.y*32+ty, cols: blockIdx.x*16+tx*2, tx*2+1
// ============================================================================

#define BM 32
#define BN 16
#define BK 16
#define PAD 17  // BK + 1

__shared__ float As[BM][PAD];
__shared__ float Bs[BK][PAD];

__global__ void __launch_bounds__(512, 3)
gemmKernel(const float* __restrict__ A,
           const float* __restrict__ B,
           float*       __restrict__ C,
           int N)
{
    const int tx = threadIdx.x;    // 0 .. 15
    const int ty = threadIdx.y;    // 0 .. 31
    const int row = blockIdx.y * BM + ty;

    // Each thread handles 2 columns of the output tile
    const int col0 = blockIdx.x * BN + tx * 2;
    const int col1 = col0 + 1;

    const int numTiles = (N + BK - 1) / BK;
    float acc0 = 0.0f;
    float acc1 = 0.0f;

    for (int t = 0; t < numTiles; ++t) {
        // ---- Load A tile ----
        {
            const int aCol = t * BK + tx * 2;
            if (row < N && aCol < N)
                As[ty][tx * 2] = A[row * N + aCol];
            else
                As[ty][tx * 2] = 0.0f;
            if (row < N && aCol + 1 < N)
                As[ty][tx * 2 + 1] = A[row * N + aCol + 1];
            else
                As[ty][tx * 2 + 1] = 0.0f;
        }

        // ---- Load B tile ----
        {
            const int bRow = t * BK + ty;
            if (bRow < N && col0 < N)
                Bs[ty][tx * 2] = B[bRow * N + col0];
            else
                Bs[ty][tx * 2] = 0.0f;
            if (bRow < N && col1 < N)
                Bs[ty][tx * 2 + 1] = B[bRow * N + col1];
            else
                Bs[ty][tx * 2 + 1] = 0.0f;
        }

        __syncthreads();

        // ---- Inner product ----
#pragma unroll
        for (int k = 0; k < BK; ++k) {
            float ak = As[ty][k];
            acc0 += ak * Bs[k][tx * 2];
            acc1 += ak * Bs[k][tx * 2 + 1];
        }

        __syncthreads();
    }

    if (row < N && col0 < N)
        C[row * N + col0] = acc0;
    if (row < N && col1 < N)
        C[row * N + col1] = acc1;
}

void launchGemm(const float* dA, const float* dB, float* dC, int N)
{
    dim3 block(BN * 2, BM);     // 32×16 = 512 threads
    dim3 grid((N + BN - 1) / BN,
              (N + BM - 1) / BM);
    gemmKernel<<<grid, block>>>(dA, dB, dC, N);
}

