// ============================================================================
// Optimized tiled GEMM with double buffering for A40 (sm_86, Ampere)
//
// BM=BN=BK=16, 16x16 block (256 threads), 6 blocks/SM → 100% occupancy.
// Double-buffering: overlap load of next tile with compute of current tile.
// Halves sync overhead from 2 to ~1 syncthreads per k-slice.
// ============================================================================

#define BM 16
#define BN 16
#define BK 16
#define PAD 17  // BK + 1

// Double-buffered shared memory
__shared__ float As[2][BM][PAD];
__shared__ float Bs[2][BK][PAD];

__global__ void __launch_bounds__(256, 6)
gemmKernel(const float* __restrict__ A,
           const float* __restrict__ B,
           float*       __restrict__ C,
           int N)
{
    const int tx = threadIdx.x;
    const int ty = threadIdx.y;
    const int row = blockIdx.y * BM + ty;
    const int col = blockIdx.x * BN + tx;

    const int numTiles = (N + BK - 1) / BK;
    float acc = 0.0f;

    if (numTiles == 0) {
        if (row < N && col < N) C[row * N + col] = 0.0f;
        return;
    }

    int cur = 0;  // current buffer: 0 or 1

    // ---- Load first tile ----
    {
        const int aCol = tx;
        if (row < N && aCol < N) As[0][ty][tx] = A[row * N + aCol];
        else As[0][ty][tx] = 0.0f;
        const int bRow = ty;
        if (bRow < N && col < N) Bs[0][ty][tx] = B[bRow * N + col];
        else Bs[0][ty][tx] = 0.0f;
    }
    __syncthreads();

    // ---- Pipeline: load next while computing current ----
    for (int t = 0; t < numTiles; ++t) {
        // ---- Compute with current tile ----
#pragma unroll
        for (int k = 0; k < BK; ++k)
            acc += As[cur][ty][k] * Bs[cur][k][tx];

        // ---- Load next tile into other buffer ----
        int nxt = 1 - cur;
        if (t + 1 < numTiles) {
            const int nt = t + 1;
            const int aCol = nt * BK + tx;
            const int bRow = nt * BK + ty;
            if (row < N && aCol < N) As[nxt][ty][tx] = A[row * N + aCol];
            else As[nxt][ty][tx] = 0.0f;
            if (bRow < N && col < N) Bs[nxt][ty][tx] = B[bRow * N + col];
            else Bs[nxt][ty][tx] = 0.0f;
        }
        __syncthreads();
        cur = nxt;
    }

    if (row < N && col < N)
        C[row * N + col] = acc;
}

void launchGemm(const float* dA, const float* dB, float* dC, int N)
{
