#include "gemm.cuh"

#include <cuda_runtime.h>

// ============================================================================
// Optimized tiled GEMM for A40 (sm_86, Ampere)
//
// BM=BN=BK=16, 16x16 block (256 threads), 6 blocks/SM → 100% occupancy.
// Uses double-buffered shared memory to hide load latency.
// Key: minimize per-iteration overhead by doing computation BEFORE sync.
// ============================================================================

#define BM 16
#define BN 16
#define BK 16
#define PAD 17  // BK + 1

// Double-buffered shared memory
__shared__ float As[2][BM][PAD];
__shared__ float Bs[2][BK][PAD];

__global__ void __launch_bounds__(256, 6)
gemmKernel(const float* __restrict__ A,
           const float* __restrict__ B,
           float*       __restrict__ C,
           int N)
{
    const int tx = threadIdx.x;
    const int ty = threadIdx.y;
    const int row = blockIdx.y * BM + ty;
    const int col = blockIdx.x * BN + tx;

    const int numTiles = (N + BK - 1) / BK;
    float acc = 0.0f;

    // Use pointer swapping for double buffering
    // Instead of arrays[2][...], use pointers
    const float* __restrict__ curAs, *curBs;
    float* __restrict__ nxtAs, *nxtBs;

    // Initial load into buffer 0
    {
        const int aCol = tx;
        if (row < N && aCol < N)
            As[0][ty][tx] = A[row * N + aCol];
        else
            As[0][ty][tx] = 0.0f;
        const int bRow = ty;
        if (bRow < N && col < N)
            Bs[0][ty][tx] = B[bRow * N + col];
        else
            Bs[0][ty][tx] = 0.0f;
    }
    __syncthreads();

    // Set up pointers for first iteration
    curAs = &As[0][0][0];
    curBs = &Bs[0][0][0];
    nxtAs = &As[1][0][0];
    nxtBs = &Bs[1][0][0];

    for (int t = 0; t < numTiles; ++t) {
        // ---- Compute ----
#pragma unroll
        for (int k = 0; k < BK; ++k)
            acc += curAs[ty * PAD + k] * curBs[k * PAD + tx];

        // ---- Load next tile ----
        if (t + 1 < numTiles) {
            int nxt = 1 - (t & 1);
            const int nt = t + 1;
            const int aCol = nt * BK + tx;
            const int bRow = nt * BK + ty;
            if (row < N && aCol < N)
                As[nxt][ty][tx] = A[row * N + aCol];
            else
                As[nxt][ty][tx] = 0.0f;
            if (bRow < N && col < N)
                Bs[nxt][ty][tx] = B[bRow * N + col];
            else
                Bs[nxt][ty][tx] = 0.0f;

            // Swap pointers
            if (nxt == 0) { curAs = &As[0][0][0]; curBs = &Bs[0][0][0]; }
            else { curAs = &As[1][0][0]; curBs = &Bs[1][0][0]; }
            __syncthreads();
        }
    }

    if (row < N && col < N)
        C[row * N + col] = acc;
}

void launchGemm(const float* dA, const float* dB, float* dC, int N)
{
    dim3 block(BN, BM);
    dim3 grid((N + BN - 1) / BN, (N + BM - 1) / BM);
    gemmKernel<<<grid, block>>>(dA, dB, dC, N);
}

#include "gemm.cuh"

#include <cuda_runtime.h>

// ============================================================================
// Optimized tiled GEMM for A40 (sm_86, Ampere)
//
// BM=BN=BK=16, 16x16 block (256 threads), 6 blocks/SM → 100% occupancy.
// Uses double buffering: while computing with tile t, load tile t+1.
// Only 1 sync per k-slice instead of 2.
// ============================================================================

#define BM 16
#define BN 16
#define BK 16
#define PAD 17  // BK + 1

__shared__ float As[2][BM][PAD];
__shared__ float Bs[2][BK][PAD];

__global__ void __launch_bounds__(256, 6)
gemmKernel(const float* __restrict__ A,
           const float* __restrict__ B,
           float*       __restrict__ C,
           int N)
{
    const int tx = threadIdx.x;
    const int ty = threadIdx.y;
    const int row = blockIdx.y * BM + ty;
    const int col = blockIdx.x * BN + tx;

    const int numTiles = (N + BK - 1) / BK;
    float acc = 0.0f;

    if (numTiles == 0) {
        if (row < N && col < N) C[row * N + col] = 0.0f;
        return;
    }

    // Load tile 0 into As[0], Bs[0]
    {
        const int aCol = tx;
        const int bRow = ty;
        if (row < N && aCol < N) As[0][ty][tx] = A[row * N + aCol];
        else As[0][ty][tx] = 0.0f;
        if (bRow < N && col < N) Bs[0][ty][tx] = B[bRow * N + col];
        else Bs[0][ty][tx] = 0.0f;
    }
    __syncthreads();

    int buf = 0;  // 0 or 1

    for (int t = 0; t < numTiles; ++t) {
        // Compute with current tile
#pragma unroll
        for (int k = 0; k < BK; ++k)
            acc += As[buf][ty][k] * Bs[buf][k][tx];

        int nxt = 1 - buf;
        if (t + 1 < numTiles) {
            // Load next tile
            const int nt = t + 1;
            const int aCol = nt * BK + tx;
            const int bRow = nt * BK + ty;
            if (row < N && aCol < N) As[nxt][ty][tx] = A[row * N + aCol];
            else As[nxt][ty][tx] = 0.0f;
            if (bRow < N && col < N) Bs[nxt][ty][tx] = B[bRow * N + col];
            else Bs[nxt][ty][tx] = 0.0f;
            __syncthreads();
            buf = nxt;
        }
    }

    if (row < N && col < N)
        C[row * N + col] = acc;
}

void launchGemm(const float* dA, const float* dB, float* dC, int N)
{
    dim3 block(BN, BM);
    dim3 grid((N + BN - 1) / BN, (N + BM - 1) / BM);
    gemmKernel<<<grid, block>>>(dA, dB, dC, N);
}

