#include "gemm.cuh"

#include <cuda_runtime.h>

// Enable internal WMMA headers
#define __CUDA_INCLUDE_COMPILER_INTERNAL_HEADERS__
#include <crt/mma.h>

using namespace nvcuda::wmma;

// ============================================================================
// WMMA TF32 GEMM for A40 (sm_86, Ampere)
//
// Each block is 16x16 threads (256 threads, 8 warps).
// Each warp computes a 16x16 output tile using one 16x16x8 WMMA operation.
// K-tile size = 8, so we need 32/8 = 4 WMMA iterations per 32-element K dimension.
//
// BM=32, BN=32, BK=8 (WMMA K dimension)
// Each warp handles 16x16 of the 32x32 output tile.
// 8 warps per block × 16x16 = 32x32 output tile per block ✓
// ============================================================================

#define WMMA_M 16
#define WMMA_N 16
#define WMMA_K 8
#define BM 32
#define BN 32

__shared__ float sA[BM][BN + 1];
__shared__ float sB[BN][BN + 1];

__global__ void gemmWmmaKernel(const float* __restrict__ A,
                               const float* __restrict__ B,
                               float*       __restrict__ C,
                               int N)
{
    int warpId = threadIdx.y * 2 + threadIdx.x / 16;  // 0..3
    int warpCol = warpId % 2;
    int warpRow = warpId / 2;

    int gRow = blockIdx.y * BM + warpRow * WMMA_M;
    int gCol = blockIdx.x * BN + warpCol * WMMA_N;

    int numK = (N + WMMA_K - 1) / WMMA_K;

    // WMMA fragments
    fragment<matrix_a, WMMA_M, WMMA_N, WMMA_K, precision::tf32, row_major> fragA;
    fragment<matrix_b, WMMA_M, WMMA_N, WMMA_K, precision::tf32, col_major> fragB;
    fragment<accumulator, WMMA_M, WMMA_N, WMMA_K, float> fragC;
    fill_fragment(fragC, 0.0f);

    for (int t = 0; t < numK; ++t) {
        // Load A tile portion (16×8)
        int aRow = gRow;
        int aCol = t * WMMA_K;
        if (aRow + WMMA_M <= N && aCol + WMMA_K <= N) {
            load_matrix_sync(fragA, &sA[aRow][aCol], BN + 1);
        } else {
            fill_fragment(fragA, 0.0f);
        }

        // Load B tile portion (8×16)
        int bRow = t * WMMA_K;
        int bCol = gCol;
        if (bRow + WMMA_K <= N && bCol + WMMA_N <= N) {
            load_matrix_sync(fragB, &sB[bRow][bCol], BN + 1);
        } else {
            fill_fragment(fragB, 0.0f);
        }

        // MMA
        mma_sync(fragC, fragA, fragB, fragC);
    }

    // Store result
    if (gRow + WMMA_M <= N && gCol + WMMA_N <= N) {
        store_matrix_sync(&C[gRow * N + gCol], fragC, N, mem_row_major);
    }
}

void launchGemm(const float* dA, const float* dB, float* dC, int N)
{
    dim3 block(BN, BM);  // 32x32 = 1024 threads = 32 warps
    dim3 grid((N + BN - 1) / BN, (N + BM - 1) / BM);
    gemmWmmaKernel<<<grid, block>>>(dA, dB, dC, N);
}

#include "gemm.cuh"

#include <cuda_runtime.h>

// Enable internal WMMA headers
#define __CUDA_INCLUDE_COMPILER_INTERNAL_HEADERS__
#include <crt/mma.h>

using namespace nvcuda::wmma;

// ============================================================================
// WMMA TF32 GEMM for A40 (sm_86, Ampere)
//
// BM=BN=32, each block computes a 32x32 output tile.
// Uses 32 warps (1024 threads) per block.
// Each warp handles 16x4 output elements using m16n4k8 WMMA.
// But we need m16n8k16 or m16n16k8...
//
// Actually: use 16 warps (512 threads) per block.
// Each warp computes a 16x8 tile (m16n8k16 with TF32).
// 16 warps × 16x8 = 16×128 elements → 16×8 per warp = 128 elements.
// Actually: 16 warps × 128 elements = 2048 elements per block.
// Output tile is 32x32 = 1024 elements. So 16 warps × 16x8 = 2048 > 1024.
//
// Simpler: 4 warps (128 threads) per block, each computing 16x8 (128 elements).
// 4 × 128 = 512 elements per block. Need 1024 / 512 = 2 blocks per tile? No.
//
// Simplest: 8 warps (256 threads) per block.
// Each warp computes 16x8 (128 elements). 8 × 128 = 1024 = 32x32. ✓
//
// But wait, TF32 WMMA uses m16n16k8. So each warp computes 16x16.
// 8 warps × 16×16 = 8 × 256 = 2048 elements > 32×32 = 1024.
// That's 2× too many.
//
// So: 4 warps × 16×16 = 4 × 256 = 1024 = 32×32. ✓
// 4 warps = 128 threads. Block: 16×8 = 128 threads.
// ============================================================================

#define WMMA_M 16
#define WMMA_N 16
#define WMMA_K 8
#define BM 32
#define BN 32

__shared__ float sA[BM][BN + 1];
__shared__ float sB[BN][BN + 1];

__global__ void gemmWmmaKernel(const float* __restrict__ A,
                               const float* __restrict__ B,
                               float*       __restrict__ C,
                               int N)
{
    int warpId = threadIdx.y * 2 + threadIdx.x / 8;  // 0..3 (4 warps)
    int warpCol = warpId % 2;
    int warpRow = warpId / 2;

    int gRow = blockIdx.y * BM + warpRow * WMMA_M;
    int gCol = blockIdx.x * BN + warpCol * WMMA_N;

    int numK = (N + WMMA_K - 1) / WMMA_K;

    // WMMA fragments
    fragment<matrix_a, WMMA_M, WMMA_N, WMMA_K, precision::tf32, row_major> fragA;
    fragment<matrix_b, WMMA_M, WMMA_N, WMMA_K, precision::tf32, col_major> fragB;
    fragment<accumulator, WMMA_M, WMMA_N, WMMA_K, float> fragC;
    fill_fragment(fragC, 0.0f);

    for (int t = 0; t < numK; ++t) {
        // Load A tile portion
        int aRow = gRow;
        int aCol = t * WMMA_K;
        if (aRow + WMMA_M <= N && aCol + WMMA_K <= N) {
            load_matrix_sync(fragA, &sA[aRow][aCol], BN + 1);
        } else {
            fill_fragment(fragA, 0.0f);
        }

        // Load B tile portion
        int bRow = t * WMMA_K;
        int bCol = gCol;
        if (bRow + WMMA_K <= N && bCol + WMMA_N <= N) {
            load_matrix_sync(fragB, &sB[bRow][bCol], BN + 1);
        } else {
            fill_fragment(fragB, 0.0f);
        }

        // MMA
        mma_sync(fragC, fragA, fragB, fragC);
    }

    // Store result
    if (gRow + WMMA_M <= N && gCol + WMMA_N <= N) {
        store_matrix_sync(&C[gRow * N + gCol], fragC, N, mem_row_major);
    }
}

void launchGemm(const float* dA, const float* dB, float* dC, int N)
{
    dim3 block(BN / 2, BM / 4);  // 16x8 = 128 threads = 4 warps
    dim3 grid((N + BN - 1) / BN, (N + BM - 1) / BM);
    gemmWmmaKernel<<<grid, block>>>(dA, dB, dC, N);
}

#include "gemm.cuh"

