#include <crt/mma.h>

using namespace nvcuda::wmma;

// ============================================================================
// WMMA TF32 GEMM for A40 (sm_86, Ampere)
//
// Block: 16x8 = 128 threads (4 warps) per 32x32 output tile.
// Shared memory tiles loaded first, then WMMA compute.
// ============================================================================

#define WMMA_M 16
#define WMMA_N 16
#define WMMA_K 8
#define BM 32
#define BN 32

__shared__ float sA[BM][BN + 1];
__shared__ float sB[BN][BN + 1];

__global__ void gemmWmmaKernel(const float* __restrict__ A,
                               const float* __restrict__ B,
                               float*       __restrict__ C,
                               int N)
{
    int warpId = threadIdx.y * 2 + threadIdx.x / 8;
    int warpCol = warpId % 2;
    int warpRow = warpId / 2;

    int gRow = blockIdx.y * BM + warpRow * WMMA_M;
    int gCol = blockIdx.x * BN + warpCol * WMMA_N;

    int numK = (N + WMMA_K - 1) / WMMA_K;

    // ---- Step 1: Load shared memory tiles ----
    {
        int tx = threadIdx.x;
        int ty = threadIdx.y;
        int row = blockIdx.y * BM + ty;
        int col = blockIdx.x * BN + tx;

        // Load a tile from A
        for (int kt = 0; kt < numK; ++kt) {
            int aRow = row;
            int aCol = kt * WMMA_K + tx;
            if (aRow < N && aCol < N)
                sA[ty][tx] = A[aRow * N + aCol];
            else
                sA[ty][tx] = 0.0f;

            int bRow = kt * WMMA_K + ty;
            int bCol = col;
            if (bRow < N && bCol < N)
                sB[ty][tx] = B[bRow * N + bCol];
            else
                sB[ty][tx] = 0.0f;
        }
        __syncthreads();
    }

    // ---- Step 2: WMMA compute ----
    fragment<matrix_a, WMMA_M, WMMA_N, WMMA_K, precision::tf32, row_major> fragA;
    fragment<matrix_b, WMMA_M, WMMA_N, WMMA_K, precision::tf32, col_major> fragB;
    fragment<accumulator, WMMA_M, WMMA_N, WMMA_K, float> fragC;
    fill_fragment(fragC, 0.0f);

    for (int t = 0; t < numK; ++t) {
        int aRow = gRow;
        int aCol = t * WMMA_K;
        if (aRow + WMMA_M <= N && aCol + WMMA_K <= N) {
            load_matrix_sync(fragA, &sA[aRow][aCol], BN + 1);
        } else {
            fill_fragment(fragA, 0.0f);
        }

        int bRow = t * WMMA_K;
        int bCol = gCol;
        if (bRow + WMMA_K <= N && bCol + WMMA_N <= N) {
            load_matrix_sync(fragB, &sB[bRow][bCol], BN + 1);
        } else {
            fill_fragment(fragB, 0.0f);
        }

        mma_sync(fragC, fragA, fragB, fragC);
    }

    if (gRow + WMMA_M <= N && gCol + WMMA_N <= N) {
        store_matrix_sync(&C[gRow * N + gCol], fragC, N, mem_row_major);
    }
}

void launchGemm(const float* dA, const float* dB, float* dC, int N)
{
    dim3 block(BN / 2, BM / 4);  // 16x8 = 128 threads = 4 warps
    dim3 grid((N + BN - 1) / BN, (N + BM - 1) / BM);
    gemmWmmaKernel<<<grid, block>>>(dA, dB, dC, N);
}

#include "gemm.cuh"

#include <cuda_runtime.h>

// Enable internal WMMA headers
#define __CUDA_INCLUDE_COMPILER_INTERNAL_HEADERS__
#include <crt/mma.h>

using namespace nvcuda::wmma;

// ============================================================================
// WMMA TF32 GEMM for A40 (sm_86, Ampere)
//
// BM=BN=32 output tile per block.
// Block: 16x8 = 128 threads (4 warps).
// Each warp computes one 16x16 output tile using m16n16k8 TF32 WMMA.
// 4 warps × 16×16 = 1024 = 32×32 output tile per block. ✓
//
// K-dimension is split into WMMA_K=8 slices.
// Each warp does numK = N/8 WMMA operations per k-slice.
// ============================================================================

#define WMMA_M 16
#define WMMA_N 16
#define WMMA_K 8
#define BM 32
#define BN 32

__shared__ float sA[BM][BN + 1];  // 32x33
__shared__ float sB[BN][BN + 1];  // 32x33

__global__ void gemmWmmaKernel(const float* __restrict__ A,
                               const float* __restrict__ B,
                               float*       __restrict__ C,
                               int N)
{
    int warpId = threadIdx.y * 2 + threadIdx.x / 8;
    int warpCol = warpId % 2;
    int warpRow = warpId / 2;

    int gRow = blockIdx.y * BM + warpRow * WMMA_M;
    int gCol = blockIdx.x * BN + warpCol * WMMA_N;

    int numK = (N + WMMA_K - 1) / WMMA_K;

    // WMMA fragments
    fragment<matrix_a, WMMA_M, WMMA_N, WMMA_K, precision::tf32, row_major> fragA;
    fragment<matrix_b, WMMA_M, WMMA_N, WMMA_K, precision::tf32, col_major> fragB;
    fragment<accumulator, WMMA_M, WMMA_N, WMMA_K, float> fragC;
    fill_fragment(fragC, 0.0f);

    for (int t = 0; t < numK; ++t) {
        // ---- Load A k-slice into shared memory ----
        // Each thread loads one element: thread (tx,ty) loads sA[ty][tx]
        // A k-slice: A[blockIdx.y*BM + ty][t*WMMA_K + tx]
        {
            const int tx = threadIdx.x;
            const int ty = threadIdx.y;
            const int aRow = blockIdx.y * BM + ty;
            const int aCol = t * WMMA_K + tx;
            if (aRow < N && aCol < N)
                sA[ty][tx] = A[aRow * N + aCol];
            else
                sA[ty][tx] = 0.0f;

            const int bRow = t * WMMA_K + ty;
            const int bCol = blockIdx.x * BN + tx;
            if (bRow < N && bCol < N)
                sB[ty][tx] = B[bRow * N + bCol];
            else
                sB[ty][tx] = 0.0f;
        }
        __syncthreads();

        // ---- WMMA load and compute ----
        int aRow = gRow;
        int aCol = t * WMMA_K;
        if (aRow + WMMA_M <= N && aCol + WMMA_K <= N)
            load_matrix_sync(fragA, &sA[aRow][aCol], BN + 1);
        else
            fill_fragment(fragA, 0.0f);

        int bRow = t * WMMA_K;
        int bCol = gCol;
        if (bRow + WMMA_K <= N && bCol + WMMA_N <= N)
            load_matrix_sync(fragB, &sB[bRow][bCol], BN + 1);
        else
            fill_fragment(fragB, 0.0f);

        mma_sync(fragC, fragA, fragB, fragC);
        __syncthreads();
    }

    // Store result
    if (gRow + WMMA_M <= N && gCol + WMMA_N <= N) {
        store_matrix_sync(&C[gRow * N + gCol], fragC, N, mem_row_major);
    }
}

void launchGemm(const float* dA, const float* dB, float* dC, int N)
{
    dim3 block(BN / 2, BM / 4);  // 16x8 = 128 threads
    dim3 grid((N + BN - 1) / BN, (N + BM - 1) / BM);
    gemmWmmaKernel<<<grid, block>>>(dA, dB, dC, N);
}

