#include "gemm.cuh"

#include <cuda_runtime.h>

// Use WMMA TF32 Tensor Cores on A40 for ~3x speedup over FP32 scalar
#define __CUDA_INCLUDE_COMPILER_INTERNAL_HEADERS__
#include <crt/mma.h>

using namespace nvcuda::wmma;

// ============================================================================
// TF32 WMMA GEMM for A40
//
// Block: 16x8 = 128 threads (4 warps).
// Each warp computes a 16x16 output tile using m16n16k8 TF32 WMMA.
// 4 warps × 16×16 = 1024 = 32×32 output tile per block.
//
// BM=BN=32, WMMA_K=8 → numK = N/8 WMMA ops per warp.
// Shared memory tiles: 32x33, loaded by all 128 threads.
// ============================================================================

#define WMMA_K 8
#define BM 32
#define BN 32
#define PAD 33

__shared__ float sA[BM][PAD];
__shared__ float sB[BN][PAD];

__global__ void __launch_bounds__(128, 8)
gemmWmmaKernel(const float* __restrict__ A,
               const float* __restrict__ B,
               float*       __restrict__ C,
               int N)
{
    int tx = threadIdx.x;
    int ty = threadIdx.y;
    int warpId = threadIdx.y * 2 + threadIdx.x / 8;  // 0..3
    int warpCol = warpId % 2;
    int warpRow = warpId / 2;

    int gRow = blockIdx.y * BM + warpRow * 16;
    int gCol = blockIdx.x * BN + warpCol * 16;

    int numK = (N + WMMA_K - 1) / WMMA_K;

    // Shared memory load + WMMA compute
    for (int t = 0; t < numK; ++t) {
        // ---- Load shared memory tiles ----
        // Thread (tx,ty) where tx=0..15, ty=0..7
        // Load A: sA[ty][tx] from A[row][t*WMMA_K+tx]
        {
            const int aRow = blockIdx.y * BM + ty;
            const int aCol = t * WMMA_K + tx;
            if (aRow < N && aCol < N)
                sA[ty][tx] = A[aRow * N + aCol];
            else
                sA[ty][tx] = 0.0f;
        }
        // Load B: sB[ty][tx] from B[t*WMMA_K+ty][col]
        {
            const int bRow = t * WMMA_K + ty;
            const int bCol = blockIdx.x * BN + tx;
            if (bRow < N && bCol < N)
                sB[ty][tx] = B[bRow * N + bCol];
            else
                sB[ty][tx] = 0.0f;
        }
        __syncthreads();

        // ---- WMMA load + compute ----
        // Warp loads 16x8 of A and 8x16 of B from shared memory
        int aRow = gRow;
        int aCol = t * WMMA_K;
        int bRow = t * WMMA_K;
        int bCol = gCol;

        fragment<matrix_a, 16, 16, WMMA_K, precision::tf32, row_major> fa;
        fragment<matrix_b, 16, 16, WMMA_K, precision::tf32, col_major> fb;
        fragment<accumulator, 16, 16, WMMA_K, float> fc;
        fill_fragment(fc, 0.0f);

        if (aRow + 16 <= N && aCol + WMMA_K <= N)
            load_matrix_sync(fa, &sA[aRow][aCol], PAD);
        else
            fill_fragment(fa, 0.0f);

        if (bRow + WMMA_K <= N && bCol + 16 <= N)
            load_matrix_sync(fb, &sB[bRow][bCol], PAD);
        else
            fill_fragment(fb, 0.0f);

        mma_sync(fc, fa, fb, fc);

        // Store result
        if (aRow + 16 <= N && bCol + 16 <= N)
            store_matrix_sync(&C[(aRow)*N + bCol], fc, N, mem_row_major);
    }
}

void launchGemm(const float* dA, const float* dB, float* dC, int N)
{
    dim3 block(BN / 2, BM / 8);  // 16x4 = 64 threads? No...
    dim3 grid((N + BN - 1) / BN, (N + BM - 1) / BM);
    gemmWmmaKernel<<<grid, block>>>(dA, dB, dC, N);
}

