    int laneIdx = threadIdx.x % 32;
    int blockWarp = blockIdx.y * gridDim.x + blockIdx.x;
    int totalWarpsPerDim = (N + 15) / 16;

    int blockCol = blockWarp % totalWarpsPerDim;
    int blockRow = blockWarp / totalWarpsPerDim;

    int gRow = blockRow * 16;
    int gCol = blockCol * 16;

    if (gRow + 16 > N || gCol + 16 > N) return;

    int numK = (N + 7) / 8;

    fragment<matrix_a, 16, 16, 8, precision::tf32, row_major> fa;
    fragment<matrix_b, 16, 16, 8, precision::tf32, col_major> fb;
    fragment<accumulator, 16, 16, 8, float> fc;
