        load_matrix_sync(fa, &A[(gRow)*N + t*8], N);
        load_matrix_sync(fb, &B[(t*8)*N + gCol], N);
        mma_sync(fc, fa, fb, fc);
    }

    store_matrix_sync(&C[gRow * N + gCol], fc, N, mem_row_major);
}

int main() {
    int N = 256;
    size_t bytes = N * N * sizeof(float);
    float *hA = (float*)malloc(bytes), *hB = (float*)malloc(bytes), *hC = (float*)malloc(bytes);

    for (int i = 0; i < N; i++)
        for (int j = 0; j < N; j++) {
            hA[i*N+j] = (rand()%1000)/1000.0 - 0.5;
            hB[i*N+j] = (rand()%1000)/1000.0 - 0.5;
            hC[i*N+j] = 0.0f;
        }

    float *dA, *dB, *dC;
    cudaMalloc(&dA, bytes); cudaMalloc(&dB, bytes); cudaMalloc(&dC, bytes);
    cudaMemcpy(dA, hA, bytes, cudaMemcpyHostToDevice);
    cudaMemcpy(dB, hB, bytes, cudaMemcpyHostToDevice);

    int totalWarps = ((N+15)/16) * ((N+15)/16);
    int blocks = (totalWarps + 127) / 128;

    tf32GemmKernel<<<blocks, 128>>>(dA, dB, dC, N);
    cudaDeviceSynchronize();

    cudaMemcpy(hC, dC, bytes, cudaMemcpyDeviceToHost);

    // CPU reference (simple)
    float *hR = (float*)malloc(bytes);
    for (int i = 0; i < N; i++)
        for (int j = 0; j < N; j++) {
            double acc = 0;
            for (int k = 0; k < N; k++)
                acc += (double)hA[i*N+k] * (double)hB[k*N+j];
            hR[i*N+j] = (float)acc;
        }

    double mse = 0;
    for (int i = 0; i < N*N; i++) {
        double d = (double)hC[i] - (double)hR[i];
        mse += d * d;
    }
    mse /= N*N;
    printf("N=%d MSE=%.6e\n", N, mse);

    free(hA); free(hB); free(hC); free(hR);
    cudaFree(dA); cudaFree(dB); cudaFree(dC);
    return 0;
}
