#include "gemm.cuh"

#include <cuda_runtime.h>

// ============================================================================
// Optimized tiled GEMM for A40 (sm_86, Ampere)
//
// BM=BN=32, BK=32, 16x16 block = 256 threads.
// Register blocking: each thread handles 2x2 output elements (128 MACs/k-slice).
// Shared memory: As[32][33], Bs[33][33] with 33-padded for zero bank conflicts.
// ============================================================================

#define BM 32
#define BN 32
#define BK 32
#define PAD 33

__shared__ float As[BM][PAD];
__shared__ float Bs[BM][PAD];

__global__ void __launch_bounds__(256, 1)
gemmKernel(const float* __restrict__ A,
           const float* __restrict__ B,
           float*       __restrict__ C,
           int N)
{
    const int tx = threadIdx.x;
    const int ty = threadIdx.y;

    const int row0 = blockIdx.y * BM + ty * 2;
    const int row1 = row0 + 1;
    const int col0 = blockIdx.x * BN + tx * 2;
    const int col1 = col0 + 1;

    const int numTiles = (N + BK - 1) / BK;
    float acc00 = 0.0f, acc01 = 0.0f;
    float acc10 = 0.0f, acc11 = 0.0f;

    for (int t = 0; t < numTiles; ++t) {
        // ---- Load A tile ----
        {
            const int aCol0 = t * BK + tx * 2;
            const int aCol1 = aCol0 + 1;
            if (row0 < N && aCol0 < N) As[ty*2][tx*2] = A[row0 * N + aCol0];
            else As[ty*2][tx*2] = 0.0f;
            if (row0 < N && aCol1 < N) As[ty*2][tx*2+1] = A[row0 * N + aCol1];
            else As[ty*2][tx*2+1] = 0.0f;
            if (row1 < N && aCol0 < N) As[ty*2+1][tx*2] = A[row1 * N + aCol0];
            else As[ty*2+1][tx*2] = 0.0f;
            if (row1 < N && aCol1 < N) As[ty*2+1][tx*2+1] = A[row1 * N + aCol1];
            else As[ty*2+1][tx*2+1] = 0.0f;
        }

        // ---- Load B tile ----
        {
            const int bRow0 = t * BK + ty * 2;
            const int bRow1 = bRow0 + 1;
            if (bRow0 < N && col0 < N) Bs[ty*2][tx*2] = B[bRow0 * N + col0];
            else Bs[ty*2][tx*2] = 0.0f;
            if (bRow0 < N && col1 < N) Bs[ty*2][tx*2+1] = B[bRow0 * N + col1];
            else Bs[ty*2][tx*2+1] = 0.0f;
            if (bRow1 < N && col0 < N) Bs[ty*2+1][tx*2] = B[bRow1 * N + col0];
            else Bs[ty*2+1][tx*2] = 0.0f;
            if (bRow1 < N && col1 < N) Bs[ty*2+1][tx*2+1] = B[bRow1 * N + col1];
            else Bs[ty*2+1][tx*2+1] = 0.0f;
        }

        __syncthreads();

        // ---- Inner product ----
#pragma unroll
        for (int k = 0; k < BK; ++k) {
            float a0 = As[ty*2][k];
            float a1 = As[ty*2+1][k];
            float b0 = Bs[k][tx*2];
            float b1 = Bs[k][tx*2+1];
            acc00 += a0 * b0;
            acc01 += a0 * b1;
            acc10 += a1 * b0;
            acc11 += a1 * b1;
        }

        __syncthreads();
    }

    if (row0 < N && col0 < N) C[row0 * N + col0] = acc00;
    if (row0 < N && col1 < N) C[row0 * N + col1] = acc01;
    if (row1 < N && col0 < N) C[row1 * N + col0] = acc10;
    if (row1 < N && col1 < N) C[row1 * N + col1] = acc11;
}

void launchGemm(const float* dA, const float* dB, float* dC, int N)
{
    dim3 block(BN / 2, BM / 2);
    dim3 grid((N + BN - 1) / BN, (N + BM - 1) / BM);
    gemmKernel<<<grid, block>>>(dA, dB, dC, N);
}

#include "gemm.cuh"

