    float acc00=0,acc01=0,acc02=0,acc03=0;
    float acc10=0,acc11=0,acc12=0,acc13=0;
    float acc20=0,acc21=0,acc22=0,acc23=0;
    float acc30=0,acc31=0,acc32=0,acc33=0;

    for (int t = 0; t < numTiles; ++t) {
        // ---- Load A tile (64x16) ----
        const int aCol = t * BK + tx * 4;
        if (row0 < N && aCol < N) As[ty*4][tx*4] = A[row0 * N + aCol];
        else As[ty*4][tx*4] = 0.0f;
        if (row0 < N && aCol+1 < N) As[ty*4][tx*4+1] = A[row0 * N + aCol+1];
        else As[ty*4][tx*4+1] = 0.0f;
        if (row0 < N && aCol+2 < N) As[ty*4][tx*4+2] = A[row0 * N + aCol+2];
        else As[ty*4][tx*4+2] = 0.0f;
        if (row0 < N && aCol+3 < N) As[ty*4][tx*4+3] = A[row0 * N + aCol+3];
        else As[ty*4][tx*4+3] = 0.0f;
        if (row1 < N && aCol < N) As[ty*4+1][tx*4] = A[row1 * N + aCol];
        else As[ty*4+1][tx*4] = 0.0f;
        if (row1 < N && aCol+1 < N) As[ty*4+1][tx*4+1] = A[row1 * N + aCol+1];
        else As[ty*4+1][tx*4+1] = 0.0f;
        if (row1 < N && aCol+2 < N) As[ty*4+1][tx*4+2] = A[row1 * N + aCol+2];
        else As[ty*4+1][tx*4+2] = 0.0f;
        if (row1 < N && aCol+3 < N) As[ty*4+1][tx*4+3] = A[row1 * N + aCol+3];
        else As[ty*4+1][tx*4+3] = 0.0f;
        if (row2 < N && aCol < N) As[ty*4+2][tx*4] = A[row2 * N + aCol];
        else As[ty*4+2][tx*4] = 0.0f;
        if (row2 < N && aCol+1 < N) As[ty*4+2][tx*4+1] = A[row2 * N + aCol+1];
        else As[ty*4+2][tx*4+1] = 0.0f;
        if (row2 < N && aCol+2 < N) As[ty*4+2][tx*4+2] = A[row2 * N + aCol+2];
        else As[ty*4+2][tx*4+2] = 0.0f;
        if (row2 < N && aCol+3 < N) As[ty*4+2][tx*4+3] = A[row2 * N + aCol+3];
        else As[ty*4+2][tx*4+3] = 0.0f;
        if (row3 < N && aCol < N) As[ty*4+3][tx*4] = A[row3 * N + aCol];
        else As[ty*4+3][tx*4] = 0.0f;
        if (row3 < N && aCol+1 < N) As[ty*4+3][tx*4+1] = A[row3 * N + aCol+1];
        else As[ty*4+3][tx*4+1] = 0.0f;
        if (row3 < N && aCol+2 < N) As[ty*4+3][tx*4+2] = A[row3 * N + aCol+2];
        else As[ty*4+3][tx*4+2] = 0.0f;
        if (row3 < N && aCol+3 < N) As[ty*4+3][tx*4+3] = A[row3 * N + aCol+3];
        else As[ty*4+3][tx*4+3] = 0.0f;

        // ---- Load B tile (16x64) ----
        const int bRow = t * BK + ty * 4;
        if (bRow < N && col0 < N) Bs[ty*4][tx*4] = B[bRow * N + col0];
        else Bs[ty*4][tx*4] = 0.0f;
        if (bRow < N && col1 < N) Bs[ty*4][tx*4+1] = B[bRow * N + col1];
        else Bs[ty*4][tx*4+1] = 0.0f;
        if (bRow < N && col2 < N) Bs[ty*4][tx*4+2] = B[bRow * N + col2];
        else Bs[ty*4][tx*4+2] = 0.0f;
        if (bRow < N && col3 < N) Bs[ty*4][tx*4+3] = B[bRow * N + col3];
        else Bs[ty*4][tx*4+3] = 0.0f;
        if (bRow+1 < N && col0 < N) Bs[ty*4+1][tx*4] = B[(bRow+1) * N + col0];
        else Bs[ty*4+1][tx*4] = 0.0f;
        if (bRow+1 < N && col1 < N) Bs[ty*4+1][tx*4+1] = B[(bRow+1) * N + col1];
