        if (bRow+1 < N && col2 < N) Bs[ty*4+1][tx*4+2] = B[(bRow+1) * N + col2];
        else Bs[ty*4+1][tx*4+2] = 0.0f;
        if (bRow+1 < N && col3 < N) Bs[ty*4+1][tx*4+3] = B[(bRow+1) * N + col3];
        else Bs[ty*4+1][tx*4+3] = 0.0f;
        if (bRow+2 < N && col0 < N) Bs[ty*4+2][tx*4] = B[(bRow+2) * N + col0];
        else Bs[ty*4+2][tx*4] = 0.0f;
        if (bRow+2 < N && col1 < N) Bs[ty*4+2][tx*4+1] = B[(bRow+2) * N + col1];
        else Bs[ty*4+2][tx*4+1] = 0.0f;
        if (bRow+2 < N && col2 < N) Bs[ty*4+2][tx*4+2] = B[(bRow+2) * N + col2];
        else Bs[ty*4+2][tx*4+2] = 0.0f;
        if (bRow+2 < N && col3 < N) Bs[ty*4+2][tx*4+3] = B[(bRow+2) * N + col3];
        else Bs[ty*4+2][tx*4+3] = 0.0f;
        if (bRow+3 < N && col0 < N) Bs[ty*4+3][tx*4] = B[(bRow+3) * N + col0];
        else Bs[ty*4+3][tx*4] = 0.0f;
        if (bRow+3 < N && col1 < N) Bs[ty*4+3][tx*4+1] = B[(bRow+3) * N + col1];
        else Bs[ty*4+3][tx*4+1] = 0.0f;
        if (bRow+3 < N && col2 < N) Bs[ty*4+3][tx*4+2] = B[(bRow+3) * N + col2];
        else Bs[ty*4+3][tx*4+2] = 0.0f;
        if (bRow+3 < N && col3 < N) Bs[ty*4+3][tx*4+3] = B[(bRow+3) * N + col3];
        else Bs[ty*4+3][tx*4+3] = 0.0f;

        __syncthreads();

        // ---- Inner product (4x4 x 16 = 256 MACs) ----
#pragma unroll
        for (int k = 0; k < BK; ++k) {
            float a0 = As[ty*4][k];
            float a1 = As[ty*4+1][k];
            float a2 = As[ty*4+2][k];
            float a3 = As[ty*4+3][k];
            float b0 = Bs[k][tx*4];
            float b1 = Bs[k][tx*4+1];
            float b2 = Bs[k][tx*4+2];
            float b3 = Bs[k][tx*4+3];
            acc00 += a0 * b0; acc01 += a0 * b1; acc02 += a0 * b2; acc03 += a0 * b3;
            acc10 += a1 * b0; acc11 += a1 * b1; acc12 += a1 * b2; acc13 += a1 * b3;
            acc20 += a2 * b0; acc21 += a2 * b1; acc22 += a2 * b2; acc23 += a2 * b3;
            acc30 += a3 * b0; acc31 += a3 * b1; acc32 += a3 * b2; acc33 += a3 * b3;
        }

        __syncthreads();
    }

    // Store results
    if (row0 < N && col0 < N) C[row0 * N + col0] = acc00;
    if (row0 < N && col1 < N) C[row0 * N + col1] = acc01;
    if (row0 < N && col2 < N) C[row0 * N + col2] = acc02;
    if (row0 < N && col3 < N) C[row0 * N + col3] = acc03;
    if (row1 < N && col0 < N) C[row1 * N + col0] = acc10;
    if (row1 < N && col1 < N) C[row1 * N + col1] = acc11;
    if (row1 < N && col2 < N) C[row1 * N + col2] = acc12;
    if (row1 < N && col3 < N) C[row1 * N + col3] = acc13;
    if (row2 < N && col0 < N) C[row2 * N + col0] = acc20;
    if (row2 < N && col1 < N) C[row2 * N + col1] = acc21;
    if (row2 < N && col2 < N) C[row2 * N + col2] = acc22;
    if (row2 < N && col3 < N) C[row2 * N + col3] = acc23;
    if (row3 < N && col0 < N) C[row3 * N + col0] = acc30;
    if (row3 < N && col1 < N) C[row3 * N + col1] = acc31;
    if (row3 < N && col2 < N) C[row3 * N + col2] = acc32;
    if (row3 < N && col3 < N) C[row3 * N + col3] = acc33;
}

void launchGemm(const float* dA, const float* dB, float* dC, int N)
{
    dim3 block(BN / 4, BM / 4);  // 16x16 = 256 threads
    dim3 grid((N + BN - 1) / BN, (N + BM - 1) / BM);
